function drawRun(g, f, x, y, h, line, fill = null, flip = false) {
  g.save();
  g.translate(x, y);
  g.scale(flip ? -h : h, h);
  g.translate(-RUN_W / 2, -.5);
  if (fill) { g.fillStyle = fill; g.fill(RUN_SIL[f]); }
  if (line) { g.fillStyle = line; g.fill(RUN_LINE[f], 'evenodd'); }
  g.restore();
}
